package com.hashem.sms;
import android.app.*;import android.app.role.RoleManager;import android.telephony.SmsManager;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.provider.Telephony;import android.provider.ContactsContract;import android.net.Uri;import android.view.*;import android.widget.*;import android.graphics.Color;import java.io.*;import java.util.*;

public class MainActivity extends Activity{
 LinearLayout root,list; EditText search,bulkNumbers,bulkBody; Db db; int purple=Color.rgb(103,80,164); TextView title; String filter="all"; HashMap<String,String> contactCache=new HashMap<>();
 public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);build();requestPermissionsIfNeeded();}
 TextView tv(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(Color.rgb(30,30,30));t.setPadding(24,16,24,16);return t;}
 Button button(String label){Button b=new Button(this);b.setText(label);return b;}
 void build(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(8,8,8,8);root.setBackgroundColor(Color.rgb(255,251,254));
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);title=tv("هاشم SMS",24);title.setTextColor(purple);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button def=button("تعيين كتطبيق SMS");def.setOnClickListener(v->requestDefault());bar.addView(def);root.addView(bar);
  search=new EditText(this);search.setHint("بحث في المحادثات والأرقام...");search.setSingleLine();search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(android.text.Editable e){}});root.addView(search);
  LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);String[] ts={"الكل","غير مقروءة","تعذّر الإرسال","مؤرشفة","المحظورة","المهملة","رسائل جماعية","المجموعات"};String[] fs={"all","unread","failed","archived","blocked","trash","bulk","groups"};for(int i=0;i<ts.length;i++){Button x=button(ts[i]);final String f=fs[i];x.setOnClickListener(v->{filter=f;render();});tabs.addView(x,new LinearLayout.LayoutParams(0,-2,1));}HorizontalScrollView hsv=new HorizontalScrollView(this);hsv.setHorizontalScrollBarEnabled(false);hsv.addView(tabs);root.addView(hsv);
  Button compose=button("＋ رسالة جديدة");compose.setOnClickListener(v->composeDialog());root.addView(compose);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView ls=new ScrollView(this);ls.addView(list);root.addView(ls,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);render();}
 void render(){if(list==null)return;list.removeAllViews();if("bulk".equals(filter)){bulkScreen();return;}if("groups".equals(filter)){groupsScreen();return;}if("failed".equals(filter)){failedScreen();return;}CursorWrapper c=new CursorWrapper(db.listThreads(filter));String q=search.getText().toString().trim();int n=0;while(c.moveToNext()){String a=c.getString("address"),body=c.getString("body"),st=c.getString("status");if(!q.isEmpty()&&!a.contains(q)&&!body.contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);String contact=contactName(a);TextView a1=tv((contact.isEmpty()?a:contact+" · "+a)+"   ·   "+st,17);a1.setTextColor(purple);TextView b=tv(body,16);row.addView(a1);row.addView(b);row.setPadding(8,4,8,4);row.setOnClickListener(v->{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);});list.addView(row);View divider=new View(this);divider.setBackgroundColor(Color.rgb(230,225,235));list.addView(divider,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد محادثات في هذا القسم",18));}
 void failedScreen(){list.addView(tv("الرسائل التي تعذّر إرسالها",22));list.addView(tv("يمكنك مراجعة الرسالة ومحاولة إرسالها مرة أخرى.",14));android.database.Cursor c=db.list("failed");int n=0;while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),st=c.getString(c.getColumnIndexOrThrow("status"));if(!search.getText().toString().trim().isEmpty()&&!a.contains(search.getText().toString().trim())&&!body.contains(search.getText().toString().trim()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv("إلى: "+a,17));card.addView(tv(body,16));card.addView(tv("الحالة: "+st,13));Button retry=button("إعادة الإرسال");retry.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("إعادة إرسال الرسالة؟").setMessage("سيتم إرسال الرسالة مرة أخرى إلى "+a).setNegativeButton("إلغاء",null).setPositiveButton("إرسال", (d,w)->send(a,body)).show());card.addView(retry);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل فاشلة حاليًا",17));}
 void composeDialog(){composeDialog("");}void composeDialog(String addr){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText to=new EditText(this);to.setHint("رقم الهاتف");to.setText(addr);EditText body=new EditText(this);body.setHint("اكتب رسالتك");body.setMinLines(4);p.addView(to);p.addView(body);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("رسالة جديدة").setView(p).setPositiveButton("إرسال",(d,w)->send(to.getText().toString(),body.getText().toString())).setNegativeButton("إلغاء",null).setNeutralButton("جدولة",null).create();dlg.show();dlg.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{String a=to.getText().toString().trim(),b=body.getText().toString();if(a.isEmpty()||b.trim().isEmpty()){Toast.makeText(this,"أدخل الرقم ونص الرسالة",Toast.LENGTH_SHORT).show();return;}schedule(a,b);dlg.dismiss();});}
 void send(String a,String b){a=a.trim();if(a.isEmpty()||b.trim().isEmpty()){Toast.makeText(this,"أدخل رقم الهاتف ونص الرسالة",Toast.LENGTH_SHORT).show();return;}long id=db.addMessage(a,b,"out","sending");try{SmsManager sm=SmsManager.getDefault();ArrayList<String> parts=sm.divideMessage(b);ArrayList<PendingIntent> sent=new ArrayList<>(),del=new ArrayList<>();for(int i=0;i<parts.size();i++){Intent si=new Intent(this,SentReceiver.class);si.putExtra("id",id);si.setAction(getPackageName()+".SENT."+id+"."+i);Intent di=new Intent(this,DeliveredReceiver.class);di.putExtra("id",id);di.setAction(getPackageName()+".DELIVERED."+id+"."+i);sent.add(PendingIntent.getBroadcast(this,1000+(int)(id%100000)*10+i,si,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));del.add(PendingIntent.getBroadcast(this,2000+(int)(id%100000)*10+i,di,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}sm.sendMultipartTextMessage(a,null,parts,sent,del);Toast.makeText(this,"بدأت محاولة إرسال الرسالة",Toast.LENGTH_SHORT).show();}catch(Exception e){db.status(id,"failed");new AlertDialog.Builder(this).setTitle("تعذّر الإرسال").setMessage(e.getMessage()==null?"تحقق من صلاحية SMS والشبكة والشريحة.":e.getMessage()).setPositiveButton("حسنًا",null).show();}if(!"bulk".equals(filter))render();}
 void schedule(String a,String b){long when=System.currentTimeMillis()+60000;new AlertDialog.Builder(this).setTitle("جدولة الرسالة").setMessage("سيتم إرسال الرسالة بعد دقيقة واحدة.").setNegativeButton("إلغاء",null).setPositiveButton("تأكيد الجدولة",(d,w)->{try{AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);Intent i=new Intent(this,ScheduleReceiver.class);i.putExtra("address",a);i.putExtra("body",b);PendingIntent pi=PendingIntent.getBroadcast(this,(int)(System.currentTimeMillis()%100000),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.set(AlarmManager.RTC_WAKEUP,when,pi);db.addMessage(a,b,"out","scheduled");Toast.makeText(this,"تمت جدولة الرسالة بعد دقيقة",Toast.LENGTH_SHORT).show();render();}catch(Exception e){Toast.makeText(this,"تعذرت الجدولة: "+e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
 void bulkScreen(){list.addView(tv("الرسائل الجماعية",22));list.addView(tv("اكتب رقمًا في كل سطر، ويمكن إضافة الاسم بعد فاصلة: 777123456, أحمد. استخدم {name} داخل نص الرسالة للتخصيص.",14));Button imp=button("استيراد ملف نصي أو CSV");imp.setOnClickListener(v->importFile());list.addView(imp);bulkNumbers=new EditText(this);bulkNumbers.setHint("الرقم أو الرقم, الاسم — سطر لكل مستلم");bulkNumbers.setMinLines(5);bulkNumbers.setGravity(Gravity.TOP);list.addView(bulkNumbers);bulkBody=new EditText(this);bulkBody.setHint("نص الرسالة. مثال: مرحبًا {name}");bulkBody.setMinLines(4);bulkBody.setGravity(Gravity.TOP);list.addView(bulkBody);Button send=button("مراجعة ثم إرسال");send.setOnClickListener(v->confirmBulk());list.addView(send);}
 void confirmBulk(){String raw=bulkNumbers.getText().toString().trim(),body=bulkBody.getText().toString().trim();if(raw.isEmpty()||body.isEmpty()){Toast.makeText(this,"أدخل المستلمين ونص الرسالة أولًا",Toast.LENGTH_SHORT).show();return;}ArrayList<String[]> recipients=new ArrayList<>();int invalid=0;boolean firstLine=true;for(String line:raw.split("\\r?\\n")){String[] p=line.trim().split(",",2);String number=p[0].trim();if(firstLine&&(number.toLowerCase(Locale.ROOT).contains("phone")||number.toLowerCase(Locale.ROOT).contains("number")||number.contains("رقم"))){firstLine=false;continue;}firstLine=false;if(number.isEmpty())continue;number=number.replaceAll("[\\s()\\-]","");if(!number.matches("\\+?[0-9]{5,20}")){invalid++;continue;}String name=p.length>1?p[1].trim():"";recipients.add(new String[]{number,name});}if(recipients.isEmpty()){Toast.makeText(this,"لم يتم العثور على أرقام صالحة؛ استخدم رقمًا واحدًا في كل سطر.",Toast.LENGTH_LONG).show();return;}final int invalidCount=invalid;new AlertDialog.Builder(this).setTitle("تأكيد الرسائل الجماعية").setMessage("سيتم إرسال "+recipients.size()+" رسالة نصية"+(invalidCount>0+"".length()?"، وسيتم تجاهل "+invalidCount+" سطر غير صالح":"")+". قد تُحتسب رسوم من شركة الاتصالات. أرسل فقط لمن وافقوا على تلقي الرسائل.").setNegativeButton("مراجعة",null).setPositiveButton("إرسال", (d,w)->{for(String[] r:recipients){String personalized=body.replace("{name}",r[1]);send(r[0],personalized);}Toast.makeText(this,"تمت معالجة قائمة الإرسال؛ راجع حالات الرسائل لكل مستلم.",Toast.LENGTH_LONG).show();}).show();}
 void groupsScreen(){list.addView(tv("مجموعات المستلمين",22));list.addView(tv("احفظ أسماء المجموعات وأرقام أعضائها، ثم حمّل المجموعة إلى شاشة الرسائل الجماعية.",14));Button add=button("＋ إنشاء مجموعة");add.setOnClickListener(v->createGroupDialog());list.addView(add);android.database.Cursor c=db.listGroups();int n=0;while(c.moveToNext()){long gid=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name"));android.database.Cursor members=db.groupMembers(gid);int count=members.getCount();members.close();LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv(name,18));card.addView(tv(count+" مستلم",13));Button use=button("استخدام في الرسائل الجماعية");use.setOnClickListener(v->{android.database.Cursor m=db.groupMembers(gid);StringBuilder numbers=new StringBuilder();while(m.moveToNext()){if(numbers.length()>0)numbers.append('\n');numbers.append(m.getString(m.getColumnIndexOrThrow("address")));String person=m.getString(m.getColumnIndexOrThrow("name"));if(person!=null&&!person.trim().isEmpty())numbers.append(", ").append(person);}m.close();filter="bulk";render();bulkNumbers.setText(numbers.toString());});card.addView(use);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لم تنشئ أي مجموعة بعد.",16));}
 void createGroupDialog(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(this);name.setHint("اسم المجموعة، مثل العائلة أو العمل");EditText members=new EditText(this);members.setHint("رقم الهاتف, الاسم — مستلم في كل سطر");members.setMinLines(5);members.setGravity(Gravity.TOP);p.addView(name);p.addView(members);new AlertDialog.Builder(this).setTitle("إنشاء مجموعة").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ", (d,w)->{String groupName=name.getText().toString().trim(),raw=members.getText().toString().trim();if(groupName.isEmpty()||raw.isEmpty()){Toast.makeText(this,"أدخل اسم المجموعة ومستلمًا واحدًا على الأقل",Toast.LENGTH_LONG).show();return;}long gid=db.createGroup(groupName);if(gid<0){Toast.makeText(this,"تعذر حفظ المجموعة؛ قد يكون الاسم مستخدمًا من قبل",Toast.LENGTH_LONG).show();return;}int added=0;for(String line:raw.split("\\r?\\n")){String[] part=line.trim().split(",",2);String number=part[0].trim();if(number.isEmpty())continue;db.addGroupMember(gid,number,part.length>1?part[1]:"");added++;}Toast.makeText(this,"تم حفظ المجموعة: "+added+" مستلم",Toast.LENGTH_LONG).show();render();}).show();}
 void importFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,44);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==44&&c==RESULT_OK&&d!=null){try{InputStream in=getContentResolver().openInputStream(d.getData());BufferedReader br=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line).append('\n');br.close();if(bulkNumbers!=null)bulkNumbers.setText(s.toString());Toast.makeText(this,"تم تحميل محتوى الملف إلى قائمة المستلمين؛ راجعه قبل الإرسال.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"تعذّر قراءة الملف: "+e.getMessage(),Toast.LENGTH_LONG).show();}}}
 String contactName(String number){if(contactCache.containsKey(number))return contactCache.get(number);String name="";try{Uri uri=Uri.withAppendedPath(ContactsContract.PhoneLookup.CONTENT_FILTER_URI,Uri.encode(number));android.database.Cursor c=getContentResolver().query(uri,new String[]{ContactsContract.PhoneLookup.DISPLAY_NAME},null,null,null);if(c!=null){if(c.moveToFirst())name=c.getString(0);c.close();}}catch(Exception ignored){}contactCache.put(number,name==null?"":name);return name==null?"":name;}
 void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=23){ArrayList<String> needed=new ArrayList<>();String[] base={"android.permission.SEND_SMS","android.permission.RECEIVE_SMS","android.permission.READ_SMS","android.permission.READ_CONTACTS"};for(String p:base)if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)needed.add(p);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)needed.add("android.permission.POST_NOTIFICATIONS");if(!needed.isEmpty())requestPermissions(needed.toArray(new String[0]),5);}}
 void requestDefault(){if(Build.VERSION.SDK_INT>=29){RoleManager rm=(RoleManager)getSystemService(ROLE_SERVICE);if(rm!=null&&rm.isRoleAvailable(RoleManager.ROLE_SMS)&&!rm.isRoleHeld(RoleManager.ROLE_SMS))startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_SMS),99);}else{Intent i=new Intent(Telephony.Sms.Intents.ACTION_CHANGE_DEFAULT);i.putExtra(Telephony.Sms.Intents.EXTRA_PACKAGE_NAME,getPackageName());startActivity(i);}}
 static class CursorWrapper{android.database.Cursor c;CursorWrapper(android.database.Cursor x){c=x;}boolean moveToNext(){return c.moveToNext();}String getString(String col){return c.getString(c.getColumnIndexOrThrow(col));}void close(){c.close();}}
}
